// babel.config.js — generated by `npx expo customize babel.config.js`, moved to the repo root
// so the root Jest run finds it (jest-expo resolves Babel options from process.cwd()).
// Stryker workers (STRYKER_MUTATOR_WORKER) compile the files Stryker instrumented WITHOUT the
// Worklets plugin: Stryker injects helper functions into every mutated file, and a file-level
// 'worklet' directive would workletize them too ("stryNS_… is read-only"). Every other file keeps
// the plugin, exactly as in a normal run: without it Reanimated's hooks throw in Jest ("useAnimatedStyle
// was used without a dependency array or Babel plugin"). Worklet transforms change no behaviour when
// code runs as plain JS in Jest.
const { readFileSync } = require('node:fs');

// Stryker's instrumenter declares a namespace helper, stryNS_<hash>, in every file it mutates. The
// hash is Stryker's internal detail, so only the prefix is matched.
const STRYKER_NAMESPACE = /\bstryNS_[0-9a-f]+\b/;
// One answer per file: an instrumented file keeps its text for the whole mutation run.
const isInstrumentedByFile = new Map();

/** The file's text, or '' for a file that is gone or unreadable (it was not instrumented). */
function readIfPresent(filename) {
  try {
    return readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
}

function isInstrumentedByStryker(filename) {
  // Stryker never instruments a dependency: no node_modules file is read.
  if (filename === undefined || filename.includes('/node_modules/')) return false;
  if (!isInstrumentedByFile.has(filename)) {
    isInstrumentedByFile.set(filename, STRYKER_NAMESPACE.test(readIfPresent(filename)));
  }
  return isInstrumentedByFile.get(filename);
}

module.exports = function (api) {
  const isMutationRun = process.env.STRYKER_MUTATOR_WORKER !== undefined;
  api.cache.using(() => isMutationRun);
  return {
    presets: [['babel-preset-expo', {}]],
    overrides: isMutationRun
      ? [
          {
            test: isInstrumentedByStryker,
            presets: [['babel-preset-expo', { worklets: false, reanimated: false }]],
          },
        ]
      : [],
  };
};
